// @vitest-environment node
// WP-10: buildTokens(json) → { css, ts } (architecture §4.7). The CLI wrapper (file writing, exit code) is not
// exercised here.
//
// SPEC-NOTE (import side effects): importing scripts/tokens.mjs must NOT run the CLI (no file writes, no process.exit);
//   guard the CLI behind a main-module check.
// SPEC-NOTE (generated header): the `ts` output must contain the word "generated" (any case), e.g. the existing
//   "GENERATED by scripts/tokens.mjs … Do not edit" banner.
// SPEC-NOTE: $-prefixed keys are ignored in the light/dark comparison too (a `$note` in only one mode does not throw).
//
// SPEC-NOTE (CSS shape): the three blocks from architecture §4.7 are matched by selector with whitespace and quote
//   style normalised: `:root`, `:root[data-theme="dark"]`, `:root[data-text="large"]`. Declarations are parsed, so
//   spacing and ordering do not matter. Values are copied verbatim from the JSON (numbers stringified). Splitting
//   `:root` over several blocks is tolerated (declarations merge).
// SPEC-NOTE (names): path segments join with "-" and keys keep their own spelling (`rule-soft`, `h1-compact`,
//   numeric keys such as space.1 -> `--space-1`). The `light`/`dark` segment is NOT part of the name, so
//   `color.light.lane.review` and `color.dark.lane.review` both become `--color-lane-review`.
// SPEC-NOTE (tokens.ts, a de-facto contract; architecture §4.7 does not pin it): the `ts` string is plain TypeScript that
//   exports NUMERIC mirrors of the JSON groups `breakpoint`, `motion` and `size`, keeping the JSON key spelling
//   (quoted kebab keys) and nesting: `breakpoint["rail-full-min-vw"] === 1360`, `motion["debounce-text"] === 400`
//   (ms), `size.row.roomy === 46` (px), `size["lane-row"].normal === 23`. Strings like "46px"/"80ms" become numbers;
//   `$`-keys are skipped. The test evaluates the module after stripping `export`, `as const` and simple `: Type`
//   annotations on const declarations, so it must be self-contained (no imports).
// SPEC-NOTE (mismatch): a key present in only one of color.light / color.dark throws; the message names the key. For
//   nested keys the message contains the leaf key name (e.g. "extra"); a dotted/dashed path is also fine.
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { buildTokens } from "./tokens.mjs";

// Resolved from this file's location (frontend/scripts), so the working directory does not matter.
const REAL = JSON.parse(
  readFileSync(resolve(dirname(fileURLToPath(import.meta.url)), "..", "..", "design", "tokens.json"), "utf8"),
);

const clone = (v) => JSON.parse(JSON.stringify(v));

/** Parses CSS into Map<normalised selector, Map<prop, value>>; comments stripped, blocks with the same selector merge. */
function parseCss(css) {
  const stripped = css.replace(/\/\*[\s\S]*?\*\//g, "");
  const blocks = new Map();
  const re = /([^{}]+)\{([^{}]*)\}/g;
  let m;
  while ((m = re.exec(stripped))) {
    const selector = m[1].replace(/\s+/g, "").replace(/'/g, '"');
    const decls = blocks.get(selector) ?? new Map();
    for (const d of m[2].split(";")) {
      const i = d.indexOf(":");
      if (i < 0) continue;
      const prop = d.slice(0, i).trim();
      if (!prop) continue;
      decls.set(prop, d.slice(i + 1).trim());
    }
    blocks.set(selector, decls);
  }
  return blocks;
}

const ROOT = ":root";
const DARK = ':root[data-theme="dark"]';
const LARGE = ':root[data-text="large"]';

/** Independent flattening of the real tokens.json for count checks. */
function leaves(node, path, out) {
  for (const [k, v] of Object.entries(node)) {
    if (k.startsWith("$")) continue;
    if (v !== null && typeof v === "object") leaves(v, [...path, k], out);
    else out.push(["--" + [...path, k].join("-"), String(v)]);
  }
  return out;
}

/** Evaluates the generated tokens.ts into a plain object of its exports. */
function evalTs(ts) {
  const code = ts
    .replace(/^\s*export\s+/gm, "")
    .replace(/\s+as\s+const\b/g, "")
    .replace(/\b(const|let|var)\s+(\w+)\s*:\s*[^=]+=/g, "$1 $2 =");
  return new Function(`${code}\n;return { breakpoint, motion, size };`)();
}

const SMALL = {
  $comment: "ignored at the top level",
  font: { family: { sans: "Foo, sans-serif" }, weight: { regular: 500 } },
  size: { header: "64px", row: { roomy: "46px", tight: "34px" }, "lane-row": { normal: "23px" } },
  space: { 1: "4px", "main-pad-x-wide": "32px" },
  breakpoint: { $comment: "ignored when nested", "rail-full-min-vw": 1360, "tall-min-vh": 800 },
  motion: { fast: "80ms", "debounce-text": "400ms" },
  color: {
    light: { bg: "#F6F4EE", "rule-soft": "#E2DED2", lane: { review: "#7A55B8", todo: "#CFCAB9" } },
    dark: { bg: "#121418", "rule-soft": "#23272E", lane: { review: "#9070DC", todo: "#4A4F57" } },
  },
};

describe("buildTokens: return shape", () => {
  it("returns css and ts strings", () => {
    const out = buildTokens(clone(SMALL));
    expect(typeof out.css).toBe("string");
    expect(typeof out.ts).toBe("string");
    expect(out.css.length).toBeGreaterThan(0);
    expect(out.ts.length).toBeGreaterThan(0);
  });

  it("is deterministic and does not mutate its input", () => {
    const input = clone(SMALL);
    const first = buildTokens(input);
    expect(input).toEqual(SMALL);
    expect(buildTokens(clone(SMALL))).toEqual(first);
  });
});

describe("buildTokens: CSS flattening (synthetic input)", () => {
  const css = () => parseCss(buildTokens(clone(SMALL)).css);

  it("flattens paths to kebab custom properties in :root", () => {
    const root = css().get(ROOT);
    expect(root).toBeDefined();
    expect(root.get("--font-family-sans")).toBe("Foo, sans-serif");
    expect(root.get("--font-weight-regular")).toBe("500");
    expect(root.get("--size-header")).toBe("64px");
    expect(root.get("--size-row-roomy")).toBe("46px");
    expect(root.get("--size-lane-row-normal")).toBe("23px");
    expect(root.get("--space-1")).toBe("4px");
    expect(root.get("--space-main-pad-x-wide")).toBe("32px");
    expect(root.get("--breakpoint-rail-full-min-vw")).toBe("1360");
    expect(root.get("--motion-debounce-text")).toBe("400ms");
  });

  it("puts the light colours in :root without a light segment in the name", () => {
    const root = css().get(ROOT);
    expect(root.get("--color-bg")).toBe("#F6F4EE");
    expect(root.get("--color-rule-soft")).toBe("#E2DED2");
    expect(root.get("--color-lane-review")).toBe("#7A55B8");
    expect(root.get("--color-lane-todo")).toBe("#CFCAB9");
    expect([...root.keys()].filter((k) => /--color-(light|dark)\b/.test(k))).toEqual([]);
  });

  it('puts the dark overrides under :root[data-theme="dark"] with the same names', () => {
    const dark = css().get(DARK);
    expect(dark).toBeDefined();
    expect(dark.get("--color-bg")).toBe("#121418");
    expect(dark.get("--color-rule-soft")).toBe("#23272E");
    expect(dark.get("--color-lane-review")).toBe("#9070DC");
    expect(dark.get("--color-lane-todo")).toBe("#4A4F57");
  });

  it("emits only colour variables in the dark block, and exactly the dark leaves", () => {
    const dark = css().get(DARK);
    expect([...dark.keys()].sort()).toEqual(["--color-bg", "--color-lane-review", "--color-lane-todo", "--color-rule-soft"]);
  });

  it("keeps non-colour tokens out of the dark block", () => {
    const dark = css().get(DARK);
    for (const k of dark.keys()) expect(k.startsWith("--color-")).toBe(true);
  });

  it('emits --scale: 1.25 under :root[data-text="large"]', () => {
    const large = css().get(LARGE);
    expect(large).toBeDefined();
    expect(large.get("--scale")).toBe("1.25");
  });

  it("skips $-prefixed keys at any depth", () => {
    const out = buildTokens(clone(SMALL)).css.replace(/\/\*[\s\S]*?\*\//g, "");
    expect(out).not.toMatch(/comment/i);
    expect(out).not.toContain("ignored");
  });

  it("emits every light colour in :root exactly once", () => {
    const root = css().get(ROOT);
    const colours = [...root.keys()].filter((k) => k.startsWith("--color-")).sort();
    expect(colours).toEqual(["--color-bg", "--color-lane-review", "--color-lane-todo", "--color-rule-soft"]);
  });
});

describe("buildTokens: light/dark key mismatch fails the build", () => {
  it("throws, naming the key, when a top-level key exists only in light", () => {
    const j = clone(SMALL);
    j.color.light["only-light"] = "#111111";
    expect(() => buildTokens(j)).toThrow(/only-light/);
  });

  it("throws, naming the key, when a top-level key exists only in dark", () => {
    const j = clone(SMALL);
    j.color.dark["only-dark"] = "#222222";
    expect(() => buildTokens(j)).toThrow(/only-dark/);
  });

  it("throws, naming the key, when a nested key exists only in light", () => {
    const j = clone(SMALL);
    j.color.light.lane.extra = "#333333";
    expect(() => buildTokens(j)).toThrow(/extra/);
  });

  it("throws, naming the key, when a nested key is missing from dark", () => {
    const j = clone(SMALL);
    delete j.color.dark.lane.review;
    expect(() => buildTokens(j)).toThrow(/review/);
  });

  it("does not throw when only $-prefixed keys differ", () => {
    const j = clone(SMALL);
    j.color.light.$note = "light only";
    expect(() => buildTokens(j)).not.toThrow();
    expect(buildTokens(j).css.replace(/\/\*[\s\S]*?\*\//g, "")).not.toContain("note");
  });

  it("does not throw for the real tokens.json", () => {
    expect(() => buildTokens(clone(REAL))).not.toThrow();
  });
});

describe("buildTokens: tokens.ts (synthetic input)", () => {
  it("exports numeric breakpoint, motion and row-size values", () => {
    const t = evalTs(buildTokens(clone(SMALL)).ts);
    expect(t.breakpoint["rail-full-min-vw"]).toBe(1360);
    expect(t.breakpoint["tall-min-vh"]).toBe(800);
    expect(t.motion.fast).toBe(80);
    expect(t.motion["debounce-text"]).toBe(400);
    expect(t.size.row.roomy).toBe(46);
    expect(t.size.row.tight).toBe(34);
    expect(t.size["lane-row"].normal).toBe(23);
  });

  it("skips $-keys and carries no colours or fonts", () => {
    const { ts } = buildTokens(clone(SMALL));
    const t = evalTs(ts);
    expect(Object.keys(t.breakpoint)).not.toContain("$comment");
    expect(ts).not.toMatch(/#[0-9a-fA-F]{6}/);
    expect(ts).not.toContain("Foo");
  });

  it("marks itself as generated", () => {
    expect(buildTokens(clone(SMALL)).ts).toMatch(/generated/i);
  });
});

describe("buildTokens: real design/tokens.json", () => {
  // Built lazily inside each test so a failing/throwing generator fails tests, not collection.
  let memo;
  const built = () => (memo ??= (() => {
    const out = buildTokens(clone(REAL));
    const blocks = parseCss(out.css);
    return { out, blocks, root: blocks.get(ROOT), dark: blocks.get(DARK) };
  })());

  it("emits the three blocks", () => {
    const { blocks, root, dark } = built();
    expect(root).toBeDefined();
    expect(dark).toBeDefined();
    expect(blocks.get(LARGE)?.get("--scale")).toBe("1.25");
  });

  it("flattens known non-colour tokens verbatim", () => {
    const { root } = built();
    expect(root.get("--font-family-mono")).toBe("'IBM Plex Mono', ui-monospace, monospace");
    expect(root.get("--font-weight-semibold")).toBe("600");
    expect(root.get("--font-size-h1-compact")).toBe("28px");
    expect(root.get("--size-header")).toBe("64px");
    expect(root.get("--size-rail-full")).toBe("208px");
    expect(root.get("--size-row-roomy")).toBe("46px");
    expect(root.get("--size-row-tight")).toBe("34px");
    expect(root.get("--size-head-side-gap")).toBe("4px");
    expect(root.get("--size-lane-row-compact")).toBe("20px");
    expect(root.get("--size-track-wide")).toBe("600px");
    expect(root.get("--size-track-seg-lane")).toBe("11px");
    expect(root.get("--space-main-pad-x-wide")).toBe("32px");
    expect(root.get("--space-10")).toBe("40px");
    expect(root.get("--radius-pill")).toBe("16px");
    expect(root.get("--motion-saving-delay")).toBe("250ms");
    expect(root.get("--breakpoint-rail-full-min-vw")).toBe("1360");
    expect(root.get("--breakpoint-lists-side-by-side-min-mainw")).toBe("1140");
  });

  it("puts light colours in :root and dark values in the dark block", () => {
    const { root, dark } = built();
    expect(root.get("--color-bg")).toBe("#F6F4EE");
    expect(dark.get("--color-bg")).toBe("#121418");
    expect(root.get("--color-lane-review")).toBe("#7A55B8");
    expect(dark.get("--color-lane-review")).toBe("#9070DC");
    expect(root.get("--color-type-bug")).toBe("#B3261E");
    expect(dark.get("--color-type-bug")).toBe("#FF7A66");
    expect(root.get("--color-focus-ring")).toBe("#1F5FBF");
    expect(dark.get("--color-focus-ring")).toBe("#7FB0FF");
    expect(root.get("--color-lane-done-history")).toBe("#D9D5CA");
  });

  it("emits exactly the expected number of variables (no $comment, no light/dark names)", () => {
    const { root, dark } = built();
    const expectedDark = leaves(REAL.color.dark, ["color"], []);
    const expectedRoot = [
      ...leaves(REAL.color.light, ["color"], []),
      ...leaves(Object.fromEntries(Object.entries(REAL).filter(([k]) => k !== "color")), [], []),
    ];
    expect(dark.size).toBe(expectedDark.length);
    for (const [name, value] of expectedDark) expect(dark.get(name)).toBe(value);
    for (const [name, value] of expectedRoot) {
      if (name === "--scale") continue;
      expect(root.get(name), name).toBe(value);
    }
    const rootNames = [...root.keys()].filter((k) => k !== "--scale");
    expect(rootNames.length).toBe(expectedRoot.length);
  });

  it("never emits comment or light/dark variable names", () => {
    const { root, dark } = built();
    for (const k of [...root.keys(), ...dark.keys()]) {
      expect(k).not.toMatch(/^--(breakpoint-)?comment$|^--color-(light|dark)-/);
    }
  });

  it("exports numeric tokens.ts values from the real file", () => {
    const t = evalTs(built().out.ts);
    expect(t.breakpoint["rail-full-min-vw"]).toBe(1360);
    expect(t.breakpoint["sync-label-min-vw"]).toBe(1700);
    expect(t.breakpoint["legend-short-min-mainw"]).toBe(1300);
    expect(t.breakpoint["config-two-cols-min-mainw"]).toBe(960);
    expect(t.motion["saving-delay"]).toBe(250);
    expect(t.motion["debounce-text"]).toBe(400);
    expect(t.motion["debounce-search"]).toBe(150);
    expect(t.size.row).toEqual({ roomy: 46, compact: 38, tight: 34 });
    expect(t.size.head.roomy).toBe(40);
    expect(t.size.head.compact).toBe(32);
    expect(t.size["lane-row"]).toEqual({ normal: 23, compact: 20 });
    expect(t.size["more-bar"]).toBe(36);
    expect(Object.keys(t.breakpoint)).not.toContain("$comment");
  });
});
